import React from "react";
import "./Javascript.css"
const JavaScriptQ = () => {
    return (
        <div className="js-cheatsheet">

            <h1>⚡ JavaScript Cheat Sheet</h1>

            <p className="subtitle">
                JavaScript ke important concepts, syntax aur methods — Beginner to Intermediate
            </p>

            {/* 1. Variables */}
            <section>
                <h2>1. Variables</h2>

                <pre>{`let name = "Yash";
const age = 19;
var city = "Moradabad"; `}</pre>

                <p>let → value change ho sakti hai</p>
                <p>const → value change nahi karni</p>
                <p>var → old JavaScript variable</p>
            </section>

            {/* 2. Data Types */}
            <section>
                <h2>2. Data Types</h2>

                <pre>{`String      → "Hello"
Number      → 100
Boolean     → true / false
Undefined   → undefined
Null        → null
BigInt      → 123456789n
Symbol      → Symbol()
Object      → { name: "Yash" }
Array       →[10, 20, 30]`}</pre>
            </section>

            {/* 3. Operators */}
            <section>
                <h2>3. Operators</h2>

                <pre>{`Arithmetic:
+   Addition
    - Subtraction
    * Multiplication
    / Division
    % Remainder
    ** Power
++Increment
--Decrement

Comparison:
== Equal
    === Strict Equal
        != Not Equal
            !== Strict Not Equal
                > Greater
                < Smaller
                >= Greater or Equal
                    <= Smaller or Equal

Logical:
&& AND
    || OR
!NOT`}</pre>
            </section>

            {/* 4. If Else */}
            <section>
                <h2>4. If / Else</h2>

                <pre>{`let age = 19;

if (age >= 18) {
    console.log("Adult");
} else {
    console.log("Minor");
} `}</pre>
            </section>

            {/* 5. Else If */}
            <section>
                <h2>5. Else If</h2>

                <pre>{`let marks = 80;

if (marks >= 90) {
    console.log("A+");
} else if (marks >= 75) {
    console.log("A");
} else if (marks >= 60) {
    console.log("B");
} else {
    console.log("Fail");
} `}</pre>
            </section>

            {/* 6. Ternary */}
            <section>
                <h2>6. Ternary Operator</h2>

                <pre>{`let age = 19;

let result = age >= 18
    ? "Adult"
    : "Minor";

console.log(result); `}</pre>
            </section>

            {/* 7. Switch */}
            <section>
                <h2>7. Switch Statement</h2>

                <pre>{`let day = 2;

switch (day) {
    case 1:
        console.log("Monday");
        break;

    case 2:
        console.log("Tuesday");
        break;

    case 3:
        console.log("Wednesday");
        break;

    default:
        console.log("Invalid Day");
}`}</pre>
            </section>

            {/* 8. For Loop */}
            <section>
                <h2>8. For Loop</h2>

                <pre>{`for (let i = 1; i <= 5; i++) {
    console.log(i);
} `}</pre>
            </section>

            {/* 9. While Loop */}
            <section>
                <h2>9. While Loop</h2>

                <pre>{`let i = 1;

while (i <= 5) {
    console.log(i);
    i++;
} `}</pre>
            </section>

            {/* 10. Do While */}
            <section>
                <h2>10. Do While Loop</h2>

                <pre>{`let i = 1;

do {
    console.log(i);
    i++;
} while (i <= 5); `}</pre>
            </section>

            {/* 11. Function */}
            <section>
                <h2>11. Function</h2>

                <pre>{`function greet() {
    console.log("Hello Yash");
}

greet(); `}</pre>
            </section>

            {/* 12. Parameters */}
            <section>
                <h2>12. Function with Parameters</h2>

                <pre>{`function add(a, b) {
    return a + b;
}

let result = add(10, 20);

console.log(result); `}</pre>
            </section>

            {/* 13. Arrow Function */}
            <section>
                <h2>13. Arrow Function</h2>

                <pre>{`const add = (a, b) => {
    return a + b;
};

console.log(add(5, 10)); `}</pre>
            </section>

            {/* 14. Arrays */}
            <section>
                <h2>14. Arrays</h2>

                <pre>{`let fruits = [
    "Apple",
    "Mango",
    "Banana"
];

console.log(fruits[0]); `}</pre>
            </section>

            {/* 15. Array Methods */}
            <section>
                <h2>15. Array Methods</h2>

                <pre>{`let numbers = [1, 2, 3, 4, 5];

numbers.push(6);
numbers.pop();

numbers.unshift(0);
numbers.shift();

console.log(numbers);

map()
filter()
reduce()
forEach()
find()
includes()
indexOf()
slice()
splice()
sort()
reverse()`}</pre>
            </section>

            {/* 16. Map */}
            <section>
                <h2>16. map()</h2>

                <pre>{`let numbers = [1, 2, 3, 4];

let result = numbers.map((num) => {
    return num * 2;
});

console.log(result); `}</pre>
            </section>

            {/* 17. Filter */}
            <section>
                <h2>17. filter()</h2>

                <pre>{`let numbers = [10, 15, 20, 25, 30];

let result = numbers.filter((num) => {
    return num > 20;
});

console.log(result); `}</pre>
            </section>

            {/* 18. Reduce */}
            <section>
                <h2>18. reduce()</h2>

                <pre>{`let numbers = [10, 20, 30];

let total = numbers.reduce((sum, num) => {
    return sum + num;
}, 0);

console.log(total); `}</pre>
            </section>

            {/* 19. Objects */}
            <section>
                <h2>19. Objects</h2>

                <pre>{`let student = {
    name: "Yash",
    age: 19,
    course: "B.Tech CSE"
};

console.log(student.name);
console.log(student.age); `}</pre>
            </section>

            {/* 20. Object Methods */}
            <section>
                <h2>20. Object Methods</h2>

                <pre>{`Object.keys(student);
Object.values(student);
Object.entries(student); `}</pre>
            </section>

            {/* 21. Strings */}
            <section>
                <h2>21. String Methods</h2>

                <pre>{`let text = "JavaScript";

text.length
text.toUpperCase()
text.toLowerCase()
text.charAt(0)
text.includes("Script")
text.startsWith("Java")
text.endsWith("Script")
text.indexOf("Script")
text.slice(0, 4)
text.substring(0, 4)
text.replace("Java", "Type")
text.trim()`}</pre>
            </section>

            {/* 22. Template Literal */}
            <section>
                <h2>22. Template Literals</h2>

                <pre>{`let name = "Yash";
let age = 19;

console.log(
    \`My name is \${name} and I am \${age} years old\`
);`}</pre >
            </section >

    {/* 23. Destructuring */ }
    < section >
                <h2>23. Destructuring</h2>

                <pre>{`const person = {
    name: "Yash",
    age: 19
};

const { name, age } = person;

console.log(name);
console.log(age);`}</pre>
            </section >

    {/* 24. Spread */ }
    < section >
                <h2>24. Spread Operator</h2>

                <pre>{`let a = [1, 2, 3];
let b = [4, 5, 6];

let result = [...a, ...b];

console.log(result);`}</pre>
            </section >

    {/* 25. Rest */ }
    < section >
                <h2>25. Rest Operator</h2>

                <pre>{`function add(...numbers) {
    return numbers.reduce(
        (sum, num) => sum + num,
        0
    );
}

console.log(add(10, 20, 30));`}</pre>
            </section >

    {/* 26. DOM */ }
    < section >
                <h2>26. DOM</h2>

                <pre>{`document.getElementById("title");

document.querySelector(".box");

document.querySelectorAll("p");

element.innerText = "Hello";

element.textContent = "Hello";

element.style.color = "red";`}</pre>
            </section >

    {/* 27. Events */ }
    < section >
                <h2>27. Events</h2>

                <pre>{`button.addEventListener("click", () => {
    alert("Button Clicked!");
});`}</pre>
            </section >

    {/* 28. Local Storage */ }
    < section >
                <h2>28. Local Storage</h2>

                <pre>{`localStorage.setItem("name", "Yash");

let name = localStorage.getItem("name");

localStorage.removeItem("name");

localStorage.clear();`}</pre>
            </section >

    {/* 29. JSON */ }
    < section >
                <h2>29. JSON</h2>

                <pre>{`const user = {
    name: "Yash",
    age: 19
};

const jsonData = JSON.stringify(user);

const objectData = JSON.parse(jsonData);`}</pre>
            </section >

    {/* 30. Math */ }
    < section >
                <h2>30. Math Methods</h2>

                <pre>{`Math.round(4.6);
Math.floor(4.9);
Math.ceil(4.1);
Math.random();
Math.max(10, 20, 30);
Math.min(10, 20, 30);
Math.sqrt(25);
Math.pow(2, 3);`}</pre>
            </section >

    {/* 31. Date */ }
    < section >
                <h2>31. Date</h2>

                <pre>{`const date = new Date();

date.getFullYear();
date.getMonth();
date.getDate();
date.getDay();
date.getHours();
date.getMinutes();`}</pre>
            </section >

    {/* 32. Promise */ }
    < section >
                <h2>32. Promise</h2>

                <pre>{`const promise = new Promise((resolve, reject) => {

    let success = true;

    if (success) {
        resolve("Success!");
    } else {
        reject("Error!");
    }

});

promise
    .then(result => console.log(result))
    .catch(error => console.log(error));`}</pre>
            </section >

    {/* 33. Async Await */ }
    < section >
                <h2>33. Async / Await</h2>

                <pre>{`async function getData() {

    const response = await fetch(
        "https://api.example.com/data"
    );

    const data = await response.json();

    console.log(data);
}

getData();`}</pre>
            </section >

    {/* 34. Try Catch */ }
    < section >
                <h2>34. Try / Catch</h2>

                <pre>{`try {
    let result = 10 / 0;
    console.log(result);
} catch (error) {
    console.log(error);
} finally {
    console.log("Completed");
}`}</pre>
            </section >

    {/* 35. Console */ }
    < section >
                <h2>35. Console Methods</h2>

                <pre>{`console.log("Hello");

console.error("Error");

console.warn("Warning");

console.table(["HTML", "CSS", "JavaScript"]);

console.clear();`}</pre>
            </section >

    {/* Footer */ }
    < div className = "js-footer" >
                <h2>🚀 Keep Learning JavaScript</h2>
                <p>
                    Learn → Practice → Build Projects → Get Better
                </p>
            </div >

        </div >
    );
};

export default JavaScript;
